mapper.update:
UPDATE t_sys_user SET password = #{password}, password_reset = false
WHERE id = #{snapshot.userId} AND email = #{snapshot.email}
  AND email_verified_at IS NOT NULL AND enabled = true
  AND username != 'administrator' AND credential_generation = #{snapshot.generation}

UPDATE t_sys_user SET email = #{email}, email_verified_at = clock_timestamp()
WHERE id = #{snapshot.userId} AND email IS NOT DISTINCT FROM #{snapshot.email}
  AND enabled = true AND credential_generation = #{snapshot.generation}

UPDATE t_sys_user SET password = #{password}, password_reset = false
WHERE id = #{id} AND enabled = true AND password_reset = true
  AND credential_generation = #{generation}

mapper.select:
SELECT a.id, a.username, a.password, a.name, a.number, a.gender, a.birthday, a.avatar_attachment_id, a.email, a.phone, a.theme_color, a.password_reset, a.enabled, a.create_time, a.create_user, a.update_time, a.update_user, a.version FROM t_sys_user a
AND a.id IN #{id}
AND (a.username LIKE CONCAT('%', #{keyword}, '%') OR a.name LIKE CONCAT('%', #{keyword}, '%') OR a.number LIKE CONCAT('%', #{keyword}, '%'))
AND NOT EXISTS ( SELECT 1 FROM t_sys_user_assignment b WHERE b.user_id = a.id )
AND EXISTS ( SELECT 1 FROM t_sys_user_assignment b WHERE b.user_id = a.id AND b.org_id IN
#{orgId}
)
ORDER BY ${listQuery.sortColumn} ${listQuery.sortOrder}, a.id ORDER BY a.number, a.id
